module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out <= 1'b0;
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
        mul_out <= 16'b0;
    end else if (mul_en_in) begin
        mul_en_out <= 1'b1;
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
        mul_out <= mul_a_reg * mul_b_reg;
    end else begin
        mul_en_out <= 1'b0;
    end
end

endmodule
